            if (parts.length < 4 || !unitType.equals(parts[2])) {
                continue;
            }
            Long otherId = Long.valueOf(parts[0]);
            LocalDate issued = LocalDate.parse(parts[1]);
            boolean sameMonth = issued.getYear() == on.getYear() && issued.getMonth() == on.getMonth();
